int lengthOfLongestSubstring(string s) {
    unordered_map<char, int> last;                     // char -> last index it was seen
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); right++) {
        char ch = s[right];
        auto it = last.find(ch);
        if (it != last.end() && it->second >= left) {
            left = it->second + 1;                       // jump just past the earlier copy
        }
        last[ch] = right;
        best = max(best, right - left + 1);
    }
    return best;
}
